(235, 'elementor_remote_info_feed_data', 'a:3:{i:0;a:5:{s:5:\"title\";s:81:\"Introducing Site Mailer by Elementor: Improve Your WordPress Email Deliverability\";s:7:\"excerpt\";s:377:\"In the world of WordPress, managing transactional emails can be a real challenge. From emails landing in spam folders to issues with server configurations, ensuring your messages are delivered can feel overwhelming.\r\nEnter Site Mailer by Elementor—a powerful plugin designed to solve your email deliverability issues with ease, eliminating the need for complex SMTP setups.\r\n\";s:7:\"created\";i:1727247060;s:5:\"badge\";s:3:\"NEW\";s:3:\"url\";s:123:\"https://elementor.com/blog/introducing-site-mailer/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed\";}i:1;a:5:{s:5:\"title\";s:87:\"Introducing Elementor 3.24: Floating Bars, Variable Fonts, Enhanced CSS Loading & More!\";s:7:\"excerpt\";s:116:\"Elevate Your Websites with Floating Bars and Variable Fonts, Improve Performance with Enhanced CSS Loading and More!\";s:7:\"created\";i:1725891168;s:5:\"badge\";s:3:\"NEW\";s:3:\"url\";s:155:\"https://elementor.com/blog/elementor-324-floating-bars-variable-fonts-enhanced-css/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed\";}i:2;a:5:{s:5:\"title\";s:81:\"Introducing Platinum Support: Your Ultimate Solution for Superior Website Support\";s:7:\"excerpt\";s:149:\"Introducing Platinum Support: Elevate your Elementor experience with dedicated expert assistance, faster response times, and 24/7 real human support.\";s:7:\"created\";i:1723108567;s:5:\"badge\";s:3:\"NEW\";s:3:\"url\";s:128:\"https://elementor.com/blog/introducing-platinum-support/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed\";}}', 'off'),
(238, '_elementor_notifications_data', 'a:2:{s:7:\"timeout\";i:1729874887;s:5:\"value\";s:11012:\"[{\"id\":\"site-mailer-introducing\",\"title\":\"Introducing Site Mailer\",\"description\":\"Keep your WordPress emails out of the spam folder with improved deliverability and an easy setup\\u2014no need for an SMTP plugin or complicated configurations.\",\"topic\":\"Site Mailer Plugin by Elementor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/Site-mailer.png\",\"chipTags\":[\"New plugin\"],\"cta\":\"Start Free Trial\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/sm-wp-dash-whatsnew\\/\",\"conditions\":[[{\"type\":\"plugin\",\"operator\":\"!=\",\"plugin\":\"site-mailer\\/site-mailer.php\"}]]},{\"id\":\"variable-fonts-3.24\",\"title\":\"Elevate text design with Variable Fonts\",\"description\":\"Experience unparalleled fluidity in your design with precise control over text width and weight.\",\"topic\":\"New in Elementor Pro 3.24\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/3.24-variable-fonts.png\",\"chipPlan\":\"Pro\",\"chipTags\":[\"New Feature\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-3.24-blog\\/\",\"readMoreText\":\"Learn More\",\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"variable-fonts-3.24\",\"title\":\"Elevate text design with Variable Fonts\",\"description\":\"Experience unparalleled fluidity in your design with precise control over text width and weight.\",\"topic\":\"New in Elementor Pro 3.24\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/3.24-variable-fonts.png\",\"chipTags\":[\"New Feature\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-3.24-blog\\/\",\"readMoreText\":\"Learn More\",\"cta\":\"Upgrade\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-3-24-variable-fonts\\/\"},{\"id\":\"floating-bars-3.24\",\"title\":\"Increase conversion wi